const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Keechelus Lake, Washington coordinates (approximate center for defining a polygon)
  const keechelusLake = ee.Geometry.Point([-121.28, 47.35]).buffer(5000); // 5km buffer around a central point

  const startDate2024 = '2024-07-01';
  const endDate2024 = '2024-07-31';

  const startDate2025 = '2025-07-01';
  const endDate2025 = '2025-07-31';

  // 2. Data Acquisition & Check
  // Using Landsat 9 (or 8, if L9 not available for the future dates) for surface water
  // Note: These dates are in the future, so no data will be available.
  const collection2024 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(keechelusLake)
    .filterDate(startDate2024, endDate2024);

  const collection2025 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(keechelusLake)
    .filterDate(startDate2025, endDate2025);

  const size2024 = await collection2024.size().getInfo();
  const size2025 = await collection2025.size().getInfo();

  console.log(`Images for July 2024: ${size2024}`);
  console.log(`Images for July 2025: ${size2025}`);

  if (size2024 === 0 || size2025 === 0) {
    console.log("No images found for one or both comparison periods, likely due to future dates.");
    console.log("C1");
    return;
  }

  // The code below would execute if data *were* available, but it won't for future dates.
  // This part is for demonstrating the full logic in a real-world scenario if the dates were in the past.

  // 3. Processing (Water detection and cloud masking)
  // Function to mask clouds and calculate water (NDWI)
  function maskCloudsAndWater(image) {
    // Cloud mask for Landsat 8/9 surface reflectance data
    // See https://developers.google.com/earth-engine/datasets/catalog/LANDSAT_LC08_C02_T1_L2#bands
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

    // Apply the scaling factors to the optical bands.
    const opticalBands = image.select('SR_B.*').multiply(0.0000275).add(-0.2);
    image = image.addBands(opticalBands, null, true);

    // Calculate NDWI
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI'); // Green, NIR
    // Water threshold (example, can be tuned)
    const water = ndwi.gt(0.1).rename('water');

    return image.updateMask(mask).addBands(ndwi).addBands(water);
  }

  const processed2024 = collection2024.map(maskCloudsAndWater);
  const processed2025 = collection2025.map(maskCloudsAndWater);

  // Take a median composite to reduce noise/variability
  const median2024 = processed2024.median();
  const median2025 = processed2025.median();

  // Calculate water area
  const water2024 = median2024.select('water');
  const water2025 = median2025.select('water');

  // Check valid pixels after masking
  const count2024 = await water2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: keechelusLake,
    scale: 30, // Landsat resolution
    maxPixels: 1e9
  }).get('water').getInfo();

  const count2025 = await water2025.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: keechelusLake,
    scale: 30,
    maxPixels: 1e9
  }).get('water').getInfo();

  console.log(`Valid pixels 2024: ${count2024}`);
  console.log(`Valid pixels 2025: ${count2025}`);

  if (count2024 === 0 || count2025 === 0) {
    console.log("No valid pixels after cloud masking for one or both periods.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  // Calculate total water pixel count (or area, if multiplied by pixel area)
  const waterPixels2024 = await water2024.reduceRegion({
    reducer: ee.Reducer.sum(), // Sums up water (where water band is 1)
    geometry: keechelusLake,
    scale: 30,
    maxPixels: 1e9
  }).get('water').getInfo();

  const waterPixels2025 = await water2025.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: keechelusLake,
    scale: 30,
    maxPixels: 1e9
  }).get('water').getInfo();

  console.log(`Water pixels 2024: ${waterPixels2024}`);
  console.log(`Water pixels 2025: ${waterPixels2025}`);

  if (waterPixels2024 === null || waterPixels2025 === null) {
    console.log("Calculation resulted in null values.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  const areaChange = waterPixels2025 - waterPixels2024; // Positive for increase, negative for decrease

  if (areaChange < 0) {
    console.log("A"); // Water extent decreased
  } else if (areaChange > 0) {
    console.log("B"); // Water extent did not decrease (increased or stayed same)
  } else {
    console.log("B"); // Water extent stayed the same, so it did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
